-- User-approved primary-only HWP criteria. Existing policies are never overwritten.
-- Conditional and uncertain rules are retained as source data, not certified as fully evaluated.
DO $guard$
BEGIN
    IF (SELECT count(*) FROM public.department WHERE deleted_at IS NULL AND name IN
        ('금융투자학과','메카트로닉스공학과','반도체산업융합학과','산업경영학과','소프트웨어융합공학과')) <> 5 THEN
        RAISE EXCEPTION 'Primary policy import requires the five source departments';
    END IF;
    IF EXISTS (SELECT 1 FROM public.graduation_requirement r JOIN public.department d ON d.id=r.department_id
        WHERE r.major_type='PRIMARY' AND r.admission_year BETWEEN 2022 AND 2026
          AND d.name IN ('금융투자학과','메카트로닉스공학과','반도체산업융합학과','산업경영학과','소프트웨어융합공학과')) THEN
        RAISE EXCEPTION 'Primary policy rows already exist; refusing to overwrite';
    END IF;
END
$guard$;

