INSERT INTO public.graduation_requirement (entity_id,department_id,admission_year,major_type,
    min_total_credit,min_department_credit,min_foundation_credit,min_general_credit,
    source_title,source_url,evaluation_complete,policy_details,created_at,updated_at)
SELECT (item->>'entityId')::uuid,d.id,(item->>'admissionYear')::integer,'PRIMARY',
    (item->>'minTotalCredit')::numeric,(item->>'minDepartmentCredit')::numeric,
    (item->>'minFoundationCredit')::numeric,(item->>'minGeneralCredit')::numeric,
    item->>'sourceTitle',NULL,false,item->'details',now(),now()
FROM approved JOIN public.department d ON d.name=item->>'department' AND d.deleted_at IS NULL;

DO $validate$
DECLARE assignment_count integer;
BEGIN
    IF (SELECT count(*) FROM public.graduation_requirement WHERE policy_details->>'importBatch'='primary-hwp-2026-11-25') <> 23 THEN
        RAISE EXCEPTION 'Expected exactly 23 approved primary policies';
    END IF;
    IF EXISTS (
        SELECT 1 FROM public.graduation_requirement r,
            jsonb_array_elements(r.policy_details->'fixedRequirements') a
        WHERE r.policy_details->>'importBatch'='primary-hwp-2026-11-25'
          AND NOT EXISTS (SELECT 1 FROM public.course c WHERE c.code=a->>'code' AND c.is_active
            AND c.category=CASE WHEN a->>'category'='GENERAL_REQUIRED' THEN 'GENERAL_EDUCATION' ELSE 'MAJOR' END)
    ) THEN
        RAISE EXCEPTION 'A fixed source course is unavailable or has an incompatible category';
    END IF;
    INSERT INTO public.required_course (entity_id,graduation_requirement_id,course_id,category,created_at,updated_at)
    SELECT gen_random_uuid(),r.id,c.id,a->>'category',now(),now()
    FROM public.graduation_requirement r
    CROSS JOIN LATERAL jsonb_array_elements(r.policy_details->'fixedRequirements') a
    JOIN public.course c ON c.code=a->>'code'
    WHERE r.policy_details->>'importBatch'='primary-hwp-2026-11-25';
    GET DIAGNOSTICS assignment_count = ROW_COUNT;
    IF assignment_count <> 246 THEN
        RAISE EXCEPTION 'Required-course import count does not match approved data';
    END IF;
END
$validate$;
